export class Source {
    produce;
    constructor(produce) {
        this.produce = produce;
    }
    subscribe(emit) {
        this.produce(emit);
    }
}
const isArrayLike = (x) => x && typeof x.length === "number" && typeof x !== "function";
const isPromiseLike = (x) => typeof x?.then === "function";
const isReadable = (x) => typeof x?.read === "function";
export function innerFrom(input) {
    if (input instanceof Source)
        return input;
    if (isReadable(input))
        return new Source((emit) => emit(input.read()));
    if (isArrayLike(input)) {
        return new Source((emit) => {
            for (let i = 0; i < input.length; i++)
                emit(input[i]);
        });
    }
    if (isPromiseLike(input)) {
        return new Source((emit) => {
            input.then((v) => emit(v));
        });
    }
    if (Symbol.iterator in input) {
        return new Source((emit) => {
            for (const v of input)
                emit(v);
        });
    }
    throw new TypeError("not a source input");
}
export function switchEach(items, project, emit) {
    for (const item of items)
        innerFrom(project(item)).subscribe(emit);
}
export function kind(input) {
    if (input instanceof Source)
        return "source";
    if (isArrayLike(input))
        return "array-like";
    if (isPromiseLike(input))
        return "promise-like";
    return "iterable";
}
